import {calcEscape as esc,calcMoney,calcParentLabel} from './calculator-view.js';
import {calendarDate,periodText} from './polish.js';
import {todayString} from './age.js';
import {cleanName} from './profile.js';
export function calcDownload(name,content,type='text/html;charset=utf-8'){
  const url=URL.createObjectURL(new Blob([content],{type})),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);
}
export function calcDocumentPage(title,body,{simulation=false}={}){return `<!doctype html><html lang="pl"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(title)}</title><style>body{font:17px/1.7 system-ui;color:#263f62;max-width:980px;margin:auto;padding:36px}h1,h2{color:#304a91}table{border-collapse:collapse;width:100%}th,td{padding:12px;border-bottom:1px solid #dce4f2;text-align:left}.notice{padding:18px;background:#edf3ff;border:2px solid #7399d5;border-radius:14px}small{font-size:14px}a{color:#345f9f}@media print{button{display:none}.notice{border:2px solid #304a91}}</style><h1>${esc(title)}</h1>${simulation?'<p class="notice"><strong>SYMULACJA — DOKUMENT NIEWAŻNY URZĘDOWO</strong><br>Nie wysłano do urzędu ani pracodawcy. Ten podgląd nie zastępuje oryginalnego formularza ZUS, dokumentu USC ani podpisu.</p>':''}${body}<p><small>Przewodnik Przyszłej Mamy · ${calendarDate(todayString())}</small></p><button onclick="print()">Drukuj / zapisz jako PDF</button></html>`;}
export function calculatorExport(result){
  const body=`<p>Scenariusz na podstawie danych użytkownika; nie jest decyzją ani potwierdzeniem prawa do świadczenia.</p><p>Zasady ${esc(result.rulesVersion)} · ${calendarDate(result.reviewedAt)}</p>${result.warnings.map(w=>`<p class="notice">${esc(w)}</p>`).join('')}<table><tr><th>Okres</th><th>Rodzic</th><th>Daty</th><th>Kwota brutto</th></tr>${result.periods.map(p=>`<tr><td>${esc(p.title)}</td><td>${esc(calcParentLabel(result.input,p.parent))}</td><td>${esc(periodText(p,{long:true}))}</td><td>${calcMoney(p.gross)}</td></tr>`).join('')}</table><h2>Terminy</h2>${result.deadlines.map(d=>`<p><strong>${calendarDate(d.start)}</strong> — ${esc(d.title)}<br>${esc(d.description||'')}</p>`).join('')}<h2>Dokumenty</h2>${result.documents.map(d=>`<h3>${esc(calcParentLabel(result.input,d.parent))}</h3><p>${esc(d.recipient)}</p><ul>${d.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`).join('')}<h2>Źródła</h2>${result.sources.map(s=>`<p><a href="${esc(s.url)}">${esc(s.name)}</a></p>`).join('')}`;
  return calcDocumentPage(result.caseTitle||result.title,body);
}
export function createCalculatorTools({sheetContent,notify,getInput,getResult,getProfile,onImport}){
  async function simulate(operation,extra={}){const r=await fetch('/api/calculator/simulate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation,...extra})}),data=await r.json();if(!r.ok)throw new Error(data.error||'Nie udało się otworzyć symulacji.');return data;}
  function show(title,body){sheetContent(title,body);}
  const notice='<p class="calc-notice">To demonstracja działania. Nie łączymy się z mObywatelem, kontem ZUS ani rejestrem państwowym. Nie wpisuj danych logowania.</p>';
  function error(e){notify(e.message||'Nie udało się wykonać symulacji.');}
  function open(){
    show('Dokumenty i połączenia',`${notice}<div class="calc-tools-grid"><button class="secondary" data-tool="login">mObywatel — symuluj logowanie</button><button class="secondary" data-tool="insurance">ZUS — przykładowe ubezpieczenie</button><button class="secondary" data-tool="debt">Zadłużenie — symuluj zaświadczenie</button><button class="secondary" data-tool="ezla">e-ZLA — przykładowy podgląd</button><button class="secondary" data-tool="ezus">eZUS — przygotuj zapytanie</button><button class="secondary" data-tool="application">Wnioski o urlopy i świadczenia</button><button class="secondary" data-tool="usc">USC — symuluj odpis aktu</button></div><div class="calc-links"><a href="https://www.zus.pl/ezus" target="_blank" rel="noopener noreferrer">Otwórz prawdziwy portal eZUS</a><a href="https://www.gov.pl/web/cyfryzacja/rejestr-stanu-cywilnego" target="_blank" rel="noopener noreferrer">Oficjalne informacje o rejestrze USC</a></div>`);
    document.querySelectorAll('[data-tool]').forEach(button=>button.addEventListener('click',()=>tool(button.dataset.tool)));
  }
  async function tool(kind){try{
    if(kind==='login'){const data=await simulate('login');show('mObywatel — demonstracja',`${notice}<h3>Profil demonstracyjny</h3><p>${esc(data.message)}</p><p>Numer demonstracji: ${data.reference}</p><button class="primary" id="demo-insurance-next">Przejdź do przykładowych danych ZUS</button>`);document.querySelector('#demo-insurance-next').onclick=()=>tool('insurance');}
    if(kind==='insurance'){
      show('Przykładowe dane ZUS',`${notice}<label class="field-label" for="demo-variant">Zestaw do przetestowania</label><select id="demo-variant"><option value="employee">Dwoje ubezpieczonych pracowników</option><option value="business-debt">Działalność z przykładowym zadłużeniem</option><option value="uninsured">Brak tytułu chorobowego u pierwszego rodzica</option></select><button class="primary" id="demo-import">Wstaw przykładowe dane do kalkulatora</button>`);
      document.querySelector('#demo-import').onclick=async()=>{try{const data=await simulate('insurance',{variant:document.querySelector('#demo-variant').value});onImport({parents:data.parents,dataOrigin:'demo'});document.querySelector('#sheet').close();notify('Wstawiono dane przykładowe. Możesz je zmienić.');}catch(e){error(e);}};
    }
    if(kind==='ezla'){const data=await simulate('ezla'),c=data.certificates[0];show('Podgląd e-ZLA — przykład',`${notice}<h3>Przykładowe zwolnienie</h3><p>${periodText(c)} · kod ${c.code}</p><p>${esc(data.message)}</p><button class="primary" id="demo-ezla-use">Użyj przykładu w chorobowym</button>`);document.querySelector('#demo-ezla-use').onclick=()=>{onImport({focus:'sickness',sickness:{...getInput().sickness,start:c.start,days:14,certificate:'yes',pregnant:true},dataOrigin:'demo'});document.querySelector('#sheet').close();};}
    if(kind==='debt'){
      show('Zadłużenie — demonstracja',`${notice}<label class="field-label" for="demo-debt">Przykładowa kwota zadłużenia (zł)</label><input id="demo-debt" type="number" min="0" step=".01" value="${getInput().parents[0].debt||0}"><button class="primary" id="demo-debt-create">Wystaw podgląd zaświadczenia — symulacja</button>`);
      document.querySelector('#demo-debt-create').onclick=async()=>{try{const data=await simulate('debt',{debt:document.querySelector('#demo-debt').value}),body=`<p>Kwota wpisana do symulacji: <strong>${calcMoney(data.debt)}</strong></p><p>Data odniesienia kalkulatora: ${calendarDate(getInput().eventDate||todayString())}</p><p>${esc(data.message)}</p><p>Numer: ${data.reference}</p>`;show('Zaświadczenie — podgląd demonstracyjny',notice+body+'<button class="primary" id="demo-debt-download">Pobierz oznaczone zaświadczenie</button>');document.querySelector('#demo-debt-download').onclick=()=>calcDownload('DEMO-zadluzenie.html',calcDocumentPage('Zadłużenie — podgląd demonstracyjny',body,{simulation:true}));}catch(e){error(e);}};
    }
    if(kind==='ezus'){
      show('Zapytanie do eZUS — symulacja',`${notice}<label class="field-label" for="demo-question">O co chcecie zapytać?</label><textarea id="demo-question" class="calc-textarea" maxlength="3000" placeholder="Np. które dokumenty potwierdzą moje uprawnienie?"></textarea><button class="primary" id="demo-question-send">Przećwicz przekazanie zapytania</button><a class="secondary" href="https://www.zus.pl/ezus" target="_blank" rel="noopener noreferrer">Przejdź do prawdziwego eZUS</a>`);
      document.querySelector('#demo-question-send').onclick=async()=>{try{const question=document.querySelector('#demo-question').value.trim();if(!question){notify('Wpisz treść zapytania.');return;}const data=await simulate('ezus');show('Zapytanie — podgląd',notice+`<p>${esc(question)}</p><p>${esc(data.message)}</p><p>${data.reference}</p><button class="secondary" id="demo-question-download">Pobierz szkic do prawdziwego eZUS</button>`);document.querySelector('#demo-question-download').onclick=()=>calcDownload('szkic-zapytania-ezus.html',calcDocumentPage('Szkic zapytania do ZUS','<p>'+esc(question)+'</p>',{simulation:true}));}catch(e){error(e);}};
    }
    if(kind==='application')openApplication();
    if(kind==='usc')openUsc();
  }catch(e){error(e);}}
  function openApplication(){
    const result=getResult();if(!result){notify('Najpierw oblicz scenariusz, aby podstawić właściwe okresy do wniosku.');return;}
    show('Wniosek — przygotowanie demonstracji',`${notice}<form id="calc-document-form" class="calc-document-form"><label class="field-label">Rodzaj wniosku<select name="kind"><option value="parental">Urlop rodzicielski</option><option value="maternity">Urlop macierzyński / na warunkach</option><option value="supplement">Uzupełniający macierzyński</option><option value="paternity">Urlop ojcowski</option><option value="work">Łączenie rodzicielskiego z pracą</option><option value="benefit">Dane do wniosku ZUS ZAM / właściwego świadczenia</option><option value="childcare">Urlop wychowawczy / obniżenie etatu</option></select></label><label class="field-label">Rodzic / opiekun<select name="parent"><option value="0">${calcParentLabel(result.input,0)}</option><option value="1">${calcParentLabel(result.input,1)}</option></select></label><label class="field-label">Imię i nazwisko wnioskującego<input name="applicant" maxlength="200" placeholder="Możesz użyć danych przykładowych"></label><label class="field-label">Imię i nazwisko dziecka<input name="child" maxlength="200" value="${esc(getProfile().name||'')}"></label><label class="field-label">Adresat / płatnik<input name="recipient" maxlength="300" placeholder="Nazwa pracodawcy albo jednostka ZUS"></label><div class="calc-fields"><label class="field-label">Od<input type="date" name="start"></label><label class="field-label">Do<input type="date" name="end"></label></div><label class="field-label">Dodatkowe oświadczenia i szczegóły<textarea class="calc-textarea" name="additional" maxlength="5000" placeholder="Historia wykorzystanych części, drugi rodzic, wymiar pracy, dokumenty szczególne…"></textarea></label><button class="primary" type="submit">Pokaż wypełniony projekt</button></form>`);
    const form=document.querySelector('#calc-document-form');
    const setPeriod=()=>{const parent=Number(form.elements.parent.value),kind=form.elements.kind.value,part=result.periods.find(p=>p.parent===parent&&(kind==='parental'?p.id.startsWith('parental'):kind==='paternity'?p.id.startsWith('paternity'):kind==='supplement'?p.id==='supplement':kind==='maternity'?p.id.startsWith('maternity'):true));if(part){form.elements.start.value=part.start;form.elements.end.value=part.end;}};form.elements.kind.onchange=setPeriod;form.elements.parent.onchange=setPeriod;setPeriod();
    for(const name of ['applicant','child'])form.elements[name].oninput=()=>{form.elements[name].value=cleanName(form.elements[name].value);};
    form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form)),parent=Number(values.parent),doc=result.documents.find(d=>d.parent===parent),heading=form.elements.kind.selectedOptions[0].textContent;
      if(values.start&&values.end&&values.start>values.end){notify('Koniec okresu nie może poprzedzać początku.');return;}
      const body=`<p>Data sporządzenia: ${calendarDate(todayString())}</p><p>Wnioskujący: ${esc(values.applicant||'[do uzupełnienia]')}<br>Adresat: ${esc(values.recipient||doc?.recipient||'[do uzupełnienia]')}</p><h2>${esc(heading)}</h2><p>Dziecko: ${esc(values.child||'[do uzupełnienia]')}; data zdarzenia: ${calendarDate(result.input.eventDate)}.</p><p>Wnioskuję o okres od ${values.start?calendarDate(values.start):'[do uzupełnienia]'} do ${values.end?calendarDate(values.end):'[do uzupełnienia]'}.</p><p>${esc(values.additional||'Oświadczenia dotyczące drugiego rodzica, wcześniejszego wykorzystania oraz pracy wymagają sprawdzenia i uzupełnienia przed rzeczywistym złożeniem.')}</p><h3>Załączniki i informacje do sprawdzenia</h3><ul>${(doc?.items||[]).map(item=>`<li>${esc(item)}</li>`).join('')}</ul><p>Wniosek pracowniczy: dane i podpis wymagają potwierdzenia. Dla świadczenia ZUS użyj aktualnego oryginalnego formularza — ten podgląd jest zestawieniem danych, a nie jego zamiennikiem.</p>${(doc?.forms||[]).map(f=>`<p><a href="${f.url}">Oryginalny ${f.code} na stronie ZUS</a></p>`).join('')}<p>Podpis: _______________________</p>`;
      show('Projekt wniosku — symulacja',notice+body+'<div class="calc-action-row"><button class="primary" id="calc-doc-download">Pobierz projekt / drukuj do PDF</button><button class="secondary" id="calc-doc-send">Przećwicz wysłanie — symulacja</button></div><p id="calc-demo-receipt" role="status"></p>');
      document.querySelector('#calc-doc-download').onclick=()=>calcDownload('DEMO-wniosek.html',calcDocumentPage(heading,body,{simulation:true}));
      document.querySelector('#calc-doc-send').onclick=async()=>{try{const receipt=await simulate('application');document.querySelector('#calc-demo-receipt').textContent=receipt.reference+' · '+receipt.message;}catch(e){error(e);}};
    };
  }
  function openUsc(){
    show('Odpis aktu — demonstracja',`${notice}<form id="calc-usc-form"><label class="field-label">Rodzaj odpisu<select name="type"><option>Odpis skrócony aktu urodzenia</option><option>Odpis zupełny aktu urodzenia</option></select></label><label class="field-label">Imię i nazwisko dziecka<input name="child" maxlength="200" value="${esc(getProfile().name||'')}"></label><label class="field-label">Cel uzyskania<input name="purpose" maxlength="500" placeholder="Np. przygotowanie dokumentów"></label><button class="primary" type="submit">Przećwicz złożenie wniosku</button></form><a class="secondary" href="https://www.gov.pl/web/gov/uzyskaj-odpis-aktu-stanu-cywilnego-urodzenia-malzenstwa-zgonu" target="_blank" rel="noopener noreferrer">Oficjalna usługa uzyskania odpisu</a>`);
    document.querySelector('#calc-usc-form').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.currentTarget)),receipt=await simulate('usc'),body=`<p>${esc(data.type)}</p><p>Dziecko: ${esc(data.child||'[do uzupełnienia]')}</p><p>Cel: ${esc(data.purpose||'[do uzupełnienia]')}</p><p>${receipt.reference} · ${esc(receipt.message)}</p>`;show('USC — wynik symulacji',notice+body+'<button class="primary" id="calc-usc-download">Pobierz podgląd</button>');document.querySelector('#calc-usc-download').onclick=()=>calcDownload('DEMO-odpis-aktu-wniosek.html',calcDocumentPage('Wniosek o odpis — podgląd',body,{simulation:true}));}catch(errorValue){error(errorValue);}};
  }
  return {open,openApplication};
}
